content:
[
  {
    "severity": "P1明显",
    "category": "ua-default-style",
    "description": "「深色模式」「真实模式」「通知」右侧的 toggle 开关（switch）整体呈系统默认观感——白色圆形拨钮 + 灰白底槽，未与「酱园琥珀」语言融合，也未使用圆角琥珀色填充或印章质感，浮在卡片上像浏览器原生物件。",
    "suggestion": "自定义 Switch 组件：轨道使用酱色/琥珀色系（如 #7A3B1E 关闭态、#B8651E 开启态），拨钮采用品牌圆角并加微阴影，圆角半径统一为 12px。"
  },
  {
    "severity": "P2瑕疵",
    "category": "inconsistency",
    "description": "开关轨道为胶囊全圆角，但偏好区卡片内其他控件（如无）应保持一致；目前真实模式开关为「开启」态用酱色填充，与未开启的深色模式/通知开关仅靠颜色区分，缺乏一致性视觉锚点。",
    "suggestion": "为开启态统一加入「琥珀圆点 + 短横刻度」的印章式细节，或统一在开启时显示微小对勾/印章图标。"
  },
  {
    "severity": "P1明显",
    "category": "ua-default-style",
    "description": "「真实模式」项前的 🤖 robot emoji 图标和「通知」前的 🔔 bell emoji 均为系统 emoji 字体直接渲染，未做任何与品牌色或印章元素一致的描边/底色处理，与整体「酱色印章 + 琥珀点缀」语言割裂。",
    "suggestion": "替换为线性图标（lucide / 自绘），主色使用酱色 #7A3B1E，开启态辅以琥珀 #D4A24C 描边或浅琥珀底圆。"
  },
  {
    "severity": "P1明显",
    "category": "ua-default-style",
    "description": "头像圆形使用纯色酱橙填充 + 居中白色「我」字，呈现为扁平色块，缺少印章元素应有的不规则边缘、纹理或轻微旋转感，与设计语言中的「印章」核心意象脱节。",
    "suggestion": "为头像底图增加印章式不规则外缘（如 1-2px 锯齿/破损笔触）、轻微旋转（-4°~4°），并辅以极淡的纹理叠加。"
  },
  {
    "severity": "P2瑕疵",
    "category": "ua-default-style",
    "description": "「本月登记 / 待审核 / 工作空间 / 偏好 / 数据与关于」等区段小标题使用纯文字、无印章下划线或竖线装饰，与设计中「印章元素」承诺不一致。",
    "suggestion": "在区段标题前增加一枚 4×4px 酱色印章方块，或在标题下方增加 1px 琥珀色短分隔线，强化品牌识别。"
  },
  {
    "severity": "P2瑕疵",
    "category": "misalign",
    "description": "「工作空间」区下方四宫格（0/34/34/35）四张卡片的水平基线未严格对齐到同一栅格，数字与下方说明文字之间的间距在「今日待处理」与「累计完成」列明显不同。",
    "suggestion": "统一四宫格卡片为相同内边距（如 16px），数字与说明文字间距固定为 6px，强制四列等宽等高。"
  },
  {
    "severity": "P2瑕疵",
    "category": "spacing",
    "description": "「工作空间」卡与其下「登记采购单 / 登记出库单 / 问经营参谋」三个胶囊按钮之间垂直距离（≈24px）大于上方卡片之间的间距（≈12px），节奏不均匀。",
    "suggestion": "将工作空间卡与胶囊按钮组的间距统一为 16px，建立 4 / 8 / 16 / 24 节奏表。"
  },
  {
    "severity": "P2瑕疵",
    "category": "contrast",
    "description": "「登记采购单」「登记出库单」「问经营参谋」三个胶囊按钮文字颜色 #5C4A3E（估）与底色 #EFE6DA 非常接近，对比度约 3.2:1，未达 WCAG AA 4.5:1。",
    "suggestion": "将按钮文字加深至 #3D2A1F 或直接使用酱色 #7A3B1E，确保 ≥4.5:1。"
  },
  {
    "severity": "P2瑕疵",
    "category": "contrast",
    "description": "「本月登记 1 条」「待审核 0 条」上方说明小字与卡片底色对比偏弱（≈3.8:1），长时阅读易疲劳。",
    "suggestion": "小字标题色由 #8A7560 调整为 #5C4A3E 或更深，保持 ≥4.5:1。"
  },
  {
    "severity": "P1明显",
    "category": "ua-default-style",
    "description": "「清除演示数据」项最右侧未显示任何可点击指示（无 chevron、无按钮形态），与 iOS/Android 列表导航默认观感趋同，缺少品牌化点击区域或印章式进入图标。",
    "suggestion": "在行尾加入 16px 琥珀色 › chevron 图标，或整行增加轻微按下反馈态，明确可点击语义。"
  },
  {
    "severity": "P2瑕疵",
    "category": "typography",
    "description": "「进行中 34 / 待确认 34 / 累计完成 35」三处大号数字字号一致（≈28px），但「今日待处理 0」因个位数视觉重量不足，整行看上去偏小，破坏四宫格节奏。",
    "suggestion": "将所有数字统一为 tabular-nums 等宽数字 + 相同字重（600），并确保 0 也占满与 34 相同宽度（避免位数导致的视觉塌陷）。"
  },
  {
    "severity": "P2瑕疵",
    "category": "inconsistency",
    "description": "顶部「我的」标题字号与底部 TabBar「我的」选中态字号、字重几乎相同，缺少页面级标题应有的层级强化。",
    "suggestion": "将顶部「我的」加大至 20-22px / 600，并加 1-2px 印章式下划线或酱色短装饰，区别于 TabBar 12-14px 标签。"
  },
  {
    "severity": "P1明显",
    "category": "ua-default-style",
    "description": "底部 TabBar 选中态「我的」图标仅靠颜色变化（灰→酱）区分，未填充琥珀色徽标或印章点，4 个图标同尺寸同描边粗细，无法在 0.5 秒内识别当前页。",
    "suggestion": "为选中 Tab 图标下方增加 4×4px 印章方块或琥珀色圆点指示器，强化状态识别。"
  }
]
